static void* cli_thread(void* arg)
{
    (void)arg;
    char line[LINE_LEN];
    char* argv[MAX_ARGS];

    syslog(LOG_INFO, "[%s] NSH CLI started. Type 'help' for commands.\n", TAG);
    /* Diagnose console/stdin wiring: which fds does this thread inherit? */
    {
        struct stat s0, s1, sc;
        int r0 = fstat(0, &s0);
        int r1 = fstat(1, &s1);
        int rc = stat("/dev/console", &sc);
        syslog(LOG_INFO,
            "[%s] fds: stdin=%d stdout=%d isatty=%d/%d | "
            "fstat0 r=%d rdev=%08x mode=%08x | fstat1 r=%d rdev=%08x mode=%08x | "
            "/dev/console r=%d rdev=%08x mode=%08x\n", TAG,
            fileno(stdin), fileno(stdout),
            isatty(fileno(stdin)), isatty(fileno(stdout)),
            r0, r0 == 0 ? (unsigned)s0.st_rdev : 0u,
            r0 == 0 ? (unsigned)s0.st_mode : 0u,
            r1, r1 == 0 ? (unsigned)s1.st_rdev : 0u,
            r1 == 0 ? (unsigned)s1.st_mode : 0u,
            rc, rc == 0 ? (unsigned)sc.st_rdev : 0u,
            rc == 0 ? (unsigned)sc.st_mode : 0u);
    }
    pthread_mutex_lock(&g_stdout_lock);
    printf("vela> ");
    fflush(stdout);
    pthread_mutex_unlock(&g_stdout_lock);
    syslog(LOG_INFO, "[%s] prompt printed, entering read loop\n", TAG);

