void esp_lowputc_send_byte(const struct esp_uart_s *priv, char byte)
{
  uint32_t write_size;

  /* Wait for room in the TX FIFO.
   *
   * Without this wait, uart_hal_write_txfifo() simply writes nothing when the
   * FIFO is full (write_size comes back 0) and the byte is silently lost.
   * up_putc() -> this function is the console path used by syslog/printf, so
   * any output burst longer than the FIFO depth (128 bytes on ESP32-P4) was
   * being truncated.  Symptom observed on the ESP32-P4X board: ~1.5 KB of
   * ai_agent startup log vanished and the agent CLI prompt never appeared.
   *
   * Must not block before the scheduler starts, hence the up_interrupt_context()
   * guard - short bursts still go straight through.
   */

  while (uart_hal_get_txfifo_len(priv->hal) <= 1)
    {
      if (up_interrupt_context())
        {
          /* In interrupt context we cannot sleep; fall back to spinning on
           * the FIFO which drains at the configured baud rate.
           */

          continue;
        }

      usleep(100);
    }

  uart_hal_write_txfifo(priv->hal, (const uint8_t *)&byte, 1, &write_size);
}

