893: static int cli_read_line(char* line, int maxlen)
894: {
895:     int lp = 0;
896: 
897:     for (;;)
898:     {
899:         char c;
900:         ssize_t nr = read(STDIN_FILENO, &c, 1);
901:         if (nr < 0)
902:         {
903:             if (errno == EINTR)
904:                 continue;
905:             usleep(20 * 1000); /* EAGAIN: nothing buffered yet */
906:             continue;
907:         }
908:         if (nr == 0)
909:         {
910:             usleep(20 * 1000);
911:             continue;
912:         }
913: 
914:         if (g_cli_verbose)
915:             syslog(LOG_INFO, "[%s] rx 0x%02x ('%c')\n", TAG,
916:                 (unsigned char)c, (c >= 0x20 && c < 0x7f) ? c : '.');
917: 
918:         if (c == '\r' || c == '\n')
919:         {
920:             line[lp] = '\0';
921:             return lp;
922:         }
923: 
924:         if (lp < maxlen - 1)
925:             line[lp++] = c;
926:     }
927: }
