static void board_i2c_scan(FAR struct i2c_master_s *i2c, uint32_t frequency)
{
  struct i2c_msg_s msg;
  uint8_t dummy;
  uint8_t addr;
  int found = 0;

  memset(&msg, 0, sizeof(msg));
  msg.frequency = frequency;
  msg.flags     = I2C_M_READ;
  msg.buffer    = &dummy;
  msg.length    = 1;

  for (addr = 0x08; addr <= 0x77; addr++)
    {
      msg.addr = addr;
      if (I2C_TRANSFER(i2c, &msg, 1) == OK)
        {
          syslog(LOG_INFO, "I2C0 @%u Hz: device ACKs at 0x%02x\n",
                 (unsigned)frequency, addr);
          found++;
        }
    }

  syslog(LOG_INFO, "I2C0 @%u Hz: %d device(s) on the bus\n",
         (unsigned)frequency, found);
}
