/****************************************************************************
 * Name: esp_bgselftest
 *
 * Description:
 *   TEMPORARY.  Drive the NSH background path ("cmd &") automatically after
 *   boot so the fix can be verified without an interactive console.
 *
 *   "free &" used to abort the whole system: nsh_execute()'s background
 *   wrapper recurses with sh_argv = {"sh","-c",<cmdline>,NULL} and argc = 4,
 *   and when CONFIG_NSH_BUILTIN_AS_COMMAND=y the builtin-spawn dispatch that
 *   used to terminate that recursion is compiled out, so the recursive call
 *   re-enters the wrapper and strlcat()s the NULL terminator.  With the
 *   dispatch restored the recursion is caught by nsh_fileapp() and the shell
 *   returns normally.
 *
 ****************************************************************************/

#ifdef CONFIG_SYSTEM_SYSTEM
static int esp_bgselftest(int argc, FAR char *argv[])
{
  int rc;

  UNUSED(argc);
  UNUSED(argv);

  /* Let NSH finish coming up before poking at it */

  sleep(4);

  syslog(LOG_INFO, "BGSELFTEST: system(\"free &\")\n");
  rc = system("free &");
  syslog(LOG_INFO, "BGSELFTEST: free & -> rc=%d (survived)\n", rc);

  sleep(1);

  syslog(LOG_INFO, "BGSELFTEST: system(\"ls /dev &\")\n");
  rc = system("ls /dev &");
  syslog(LOG_INFO, "BGSELFTEST: ls /dev & -> rc=%d (survived)\n", rc);

  sleep(1);
  syslog(LOG_INFO, "BGSELFTEST: PASS\n");
  return 0;
}
#endif

