/* Spawn an arbitrary registered builtin by name with a trivial argv.  Used to
 * tell "task_spawn of a builtin is broken" apart from "spawning a second NSH
 * (sh) is broken".
 */

static int esp_spawn_builtin(FAR const char *name)
{
  FAR const struct builtin_s *b;
  posix_spawnattr_t attr;
  struct sched_param param;
  FAR char *argv[2];
  int idx;
  int rc;

  idx = builtin_isavail(name);
  if (idx < 0)
    {
      return -2000;
    }

  b = builtin_for_index(idx);
  if (b == NULL)
    {
      return -2001;
    }

  argv[0] = (FAR char *)name;
  argv[1] = NULL;

  rc = posix_spawnattr_init(&attr);
  if (rc != 0)
    {
      return -2002;
    }

  param.sched_priority = b->priority;
  posix_spawnattr_setschedparam(&attr, &param);
  posix_spawnattr_setstacksize(&attr, b->stacksize);
  posix_spawnattr_setflags(&attr, POSIX_SPAWN_SETSCHEDPARAM);

  rc = task_spawn(b->name, b->main, NULL, &attr, argv, NULL);
  posix_spawnattr_destroy(&attr);

  return rc < 0 ? -2003 : 0;
}

