208: static void IRAM_ATTR esp_mipi_dsi_dma_restart(
209:     FAR struct esp_mipi_dsi_priv_s *priv)
210: {
211:   FAR dw_gdma_dev_t *dev = priv->dw_hal.dev;
212:   FAR dw_gdma_link_list_item_t *lli_nc = priv->lli_nc;
213: 
214:   if (dev == NULL || lli_nc == NULL || priv->lli == NULL)
