229: /****************************************************************************
230:  * Name: esp_mipi_dsi_dma_isr
231:  *
232:  * Description:
233:  *   DW-GDMA interrupt handler. On DMA_TFR_DONE, re-arm the link list so
234:  *   continuous framebuffer streaming continues while video is enabled.
235:  *
236:  * Input Parameters:
237:  *   irq     - IRQ number (unused)
238:  *   context - Interrupt context (unused)
239:  *   arg     - Pointer to struct esp_mipi_dsi_priv_s
240:  *
241:  * Returned Value:
242:  *   Zero (OK)
243:  *
244:  ****************************************************************************/
245: 
246: static int IRAM_ATTR esp_mipi_dsi_dma_isr(int irq, FAR void *context,
247:                                           FAR void *arg)
248: {
249:   FAR struct esp_mipi_dsi_priv_s *priv =
250:     (FAR struct esp_mipi_dsi_priv_s *)arg;
251:   FAR dw_gdma_dev_t *dev;
252:   irqstate_t flags;
253:   uint32_t status;
254: 
255:   UNUSED(irq);
256:   UNUSED(context);
257: 
258:   if (priv == NULL || priv->dw_hal.dev == NULL)
259:     {
260:       return OK;
261:     }
262: 
263:   dev = priv->dw_hal.dev;
264:   flags = spin_lock_irqsave(&priv->dmalock);
265:   status = dw_gdma_ll_channel_get_intr_status(dev, ESP_MIPI_DSI_DMA_CHAN);
266:   dw_gdma_ll_channel_clear_intr(dev, ESP_MIPI_DSI_DMA_CHAN, status);
267: 
268:   if ((status & DW_GDMA_LL_CHANNEL_EVENT_DMA_TFR_DONE) != 0 &&
269:       priv->dma_enabled)
270:     {
271:       esp_mipi_dsi_dma_restart(priv);
272:     }
273: 
274:   spin_unlock_irqrestore(&priv->dmalock, flags);
275:   return OK;
276: }
