/* Bring-up trace for the DW-GDMA streaming path.
 *
 * Set to 0 (or delete together with esp_mipi_dsi_dma_trace()) once continuous
 * FB streaming is verified on hardware.  While enabled it reports, from the
 * firmware itself, whether the channel was ever armed, whether the LLI
 * terminator was reached and whether TFR_DONE keeps recurring -- three facts
 * that cannot be distinguished from the outside (a breakpoint on the ISR plus
 * a register peek cannot tell "never armed" from "completed and stopped").
 */

#define ESP_MIPI_DSI_DMA_TRACE 1

#if ESP_MIPI_DSI_DMA_TRACE
static volatile uint32_t g_dsi_dma_isr_count;
static volatile uint32_t g_dsi_dma_restart_count;

static void esp_mipi_dsi_dma_trace(FAR struct esp_mipi_dsi_priv_s *priv,
                                   FAR const char *tag)
{
  FAR dw_gdma_dev_t *dev = priv->dw_hal.dev;
  FAR dmac_channel_reg_t *ch;

  if (dev == NULL)
    {
      return;
    }

  ch = &dev->ch[ESP_MIPI_DSI_DMA_CHAN];

  syslog(LOG_INFO,
         "DSI-DMA[%s] fb=%p lli=%p nc=%p isr=%lu rst=%lu "
         "chen0=%08lx ist=%08lx cist=%08lx sar=%08lx dar=%08lx "
         "bts=%08lx ctl=%08lx llp=%08lx cfg=%08lx st=%08lx "
         "dstat=%08lx brg=%08lx\n",
         tag, priv->fb, priv->lli, priv->lli_nc,
         (unsigned long)g_dsi_dma_isr_count,
         (unsigned long)g_dsi_dma_restart_count,
         (unsigned long)dev->chen0.val,
         (unsigned long)dev->int_st0.val,
         (unsigned long)dev->common_int_st0.val,
         (unsigned long)ch->sar0.val,
