401:   uint16_t x;
402:   uint16_t y;
403:   uint8_t flags;
404:   int ret;
405: 
406:   /* Erase the Touch Sample and Touch Point */
407: 
408:   iinfo("\n");
409:   DEBUGASSERT(dev && sample);
410:   memset(sample, 0, sizeof(*sample));
411: 
412:   /* Read the Touch Panel Status */
413: 
414:   ret = gt9xx_i2c_read(dev, GTP_READ_COOR_ADDR, status, sizeof(status));
415:   if (ret < 0)
416:     {
417:       ierr("Read Touch Panel Status failed: %d\n", ret);
418:       return ret;
419:     }
420: 
421:   /* Decode the Status Code and the Touched Points */
422: 
423:   status_code = status[0] & 0x80;
424:   touched_points = status[0] & 0x0f;
425: 
426:   /* If Touch Panel Status is OK and Touched Points is 1 or more */
427: 
428:   if (status_code != 0 && touched_points >= 1)
429:     {
430:       /* Read the First Touch Point (6 bytes) */
431: 
432:       ret = gt9xx_i2c_read(dev, GTP_POINT1, touch, sizeof(touch));
433:       if (ret < 0)
434:         {
435:           ierr("Read Touch Point failed: %d\n", ret);
436:           return ret;
437:         }
438: 
439:       /* Decode the Touch Coordinates */
440: 
441:       x = touch[0] + (touch[1] << 8);
442:       y = touch[2] + (touch[3] << 8);
443: 
444:       /* Return the Touch Coordinates as Touch Down */
445: 
446:       flags = TOUCH_DOWN | TOUCH_ID_VALID | TOUCH_POS_VALID;
