CFG=cmake_out/esp32p4-function-ev-board_nsh/.config
echo "sizes: original=$(wc -c < /tmp/dotconfig.bak) current=$(wc -c < $CFG)"
echo "=== semantic diff (symbols whose SET/UNSET state or value differs) ==="
python3 - <<'PY'
def parse(p):
    d={}
    for L in open(p):
        L=L.strip()
        if L.startswith('# CONFIG_') and L.endswith(' is not set'):
            d[L[2:-11].strip()]=None
        elif L.startswith('CONFIG_') and '=' in L:
            k,v=L.split('=',1); d[k]=v
    return d
a=parse('/tmp/dotconfig.bak')
b=parse('cmake_out/esp32p4-function-ev-board_nsh/.config')
only_a={k:a[k] for k in a if k not in b}
diff={k:(a[k],b[k]) for k in a if k in b and a[k]!=b[k]}
print("in original but ABSENT now:", len(only_a))
for k,v in list(only_a.items())[:25]: print("   -",k,"=",v)
print("value/state CHANGED:", len(diff))
for k,(x,y) in list(diff.items())[:25]: print(f"   ~ {k}: {x} -> {y}")
PY

