static void display_refr_timer_cb(lv_timer_t * tmr)
{
    lv_display_t * disp = lv_timer_get_user_data(tmr);
    lv_nuttx_fb_t * dsc = lv_display_get_driver_data(disp);
    struct pollfd pfds[1];

    lv_memzero(pfds, sizeof(pfds));
    pfds[0].fd = dsc->fd;
    pfds[0].events = POLLOUT;

    /* Query free fb to draw.
     *
     * NOTE: this used to *gate* the refresh -- _lv_display_refr_timer() ran
     * only when POLLOUT came back.  That is meant for a double-buffered /
     * panning setup where the driver reports POLLOUT once a buffer is free.
     * On a plain single-buffered framebuffer (this board: one plane, LVGL in
     * LV_DISPLAY_RENDER_MODE_DIRECT straight into the mmap'd fb) NuttX's
     * fb_poll() reports POLLOUT only while its internal panbuf is not full,
     * which never holds here -- so the refresh was silently skipped forever:
     * LVGL initialised, created the widgets demo, entered the render loop and
     * never drew a single pixel (measured: flush_cb was never entered and the
     * framebuffer stayed at the boot test colour).
     *
     * The poll is still useful as a hint for a genuinely busy double-buffered
     * target, so keep it non-blocking and use its result only to avoid
     * queueing yet another frame while the driver says it is full.
     */

    if(poll(pfds, 1, 0) == 0 && (pfds[0].revents & POLLOUT) == 0 &&
       dsc->pinfo.yres_virtual > dsc->pinfo.yres) {
        /* Double buffered and no free buffer right now: try again next tick. */
        return;
    }

    _lv_display_refr_timer(tmr);
}

