memset(&hal_cfg, 0, sizeof(hal_cfg));

/* The CSI camera shares this DW-GDMA controller and is initialised before the
 * display (see esp32p4_bringup.c), so this driver must not blindly reset it.
 *
 * Both dw_gdma_ll_reset_register() and dw_gdma_hal_init() reset the *whole*
 * controller -- and dw_gdma_hal_init() does it unconditionally.  That wipes
 * the camera's channel configuration, so its capture can never start and the
 * next register access faults:
 *
 *   esp_csi_data_start_capture: ERROR: esp_cam_ctlr_start failed
 *   Store/AMO access fault, EPC in dw_gdma_channel_config_transfer,
 *   MTVAL = 0x50081100 (the DW-GDMA channel-0 register block)
 *
 * The controller's peripheral clock is the tell-tale: it is switched on by
 * the first user to acquire a group handle and gated off again by
 * dw_gdma_release_group_handle() when the last one releases.  A live bus
 * clock therefore means a sibling channel already owns controller state that
 * must survive, so only reset when we are the first user.
 *
 * Reordering the two initialisations (camera first) previously moved this
 * failure from the panel to the camera rather than removing it.
 */

if (!dw_gdma_ll_is_bus_clock_enabled(0))
  {
    PERIPH_RCC_ATOMIC()
      {
        dw_gdma_ll_enable_bus_clock(0, true);
        dw_gdma_ll_reset_register(0);
      }
  }

/* Stand up our own HAL context without the global reset that
 * dw_gdma_hal_init() performs.  The channel is configured from scratch
 * below, so it does not depend on inheriting a reset state.
 */

priv->dw_hal.dev = DW_GDMA_LL_GET_HW(0);
dw_gdma_ll_enable_controller(priv->dw_hal.dev, true);
dw_gdma_ll_enable_intr_global(priv->dw_hal.dev, true);
dev = priv->dw_hal.dev;

