    esp_os_exit_critical(&s_ctx.spinlock);

    if (!found) {
        return ESP_ERR_NOT_FOUND;
    }
    return ESP_OK;
}

esp_err_t mipi_csi_brg_declaim(int id)
{
    esp_os_enter_critical(&s_ctx.spinlock);

    s_ctx.ref_cnt[id]--;
    if (s_ctx.ref_cnt[id] < 0) {
        s_ctx.ref_cnt[id] = 0;
