#include "esp_ldo.h"
#include "esp_csi.h"

/* TEMP-CAMERA-DIAG: register-level capture probe.  Remove together with
 * esp_csi_diag()/esp_csi_diag_series() once the camera delivers frames.
 */

#include "hal/mipi_csi_host_ll.h"
#include "hal/mipi_csi_brg_ll.h"
#include "soc/dw_gdma_struct.h"

#ifdef CONFIG_ESPRESSIF_MIPI_CSI

 * Name: esp_csi_data_start_capture
 ****************************************************************************/

/* TEMP-CAMERA-DIAG: single register snapshot of the whole MIPI receive path.
 *
 * Uses the real HAL device pointers, so the offsets cannot drift from the
 * hardware definitions.  The host has no int_raw register: int_st_main is
 * read-clear, so each call reports the errors latched since the previous one.
 */

static void esp_csi_diag(FAR const char *stage)
{
  FAR csi_host_dev_t *host = MIPI_CSI_HOST_LL_GET_HW(0);
  FAR csi_brg_dev_t  *brg  = MIPI_CSI_BRG_LL_GET_HW(0);
  int i;

  _info("CAMDIAG[%s] host st_main=%08" PRIx32 " n_lanes=%u phy_rx=%08" PRIx32
        " stopstate=%08" PRIx32 " resetn=%08" PRIx32 "\n",
        stage, (uint32_t)host->int_st_main.val, (unsigned)host->n_lanes.n_lanes,
        (uint32_t)host->phy_rx.val, (uint32_t)host->phy_stopstate.val,
        (uint32_t)host->csi2_resetn.val);

  _info("CAMDIAG[%s] brg  clk_en=%u csi_en=%u host_ctrl=%08" PRIx32
        " int_raw=%08" PRIx32 " dtype=%08" PRIx32 " frame=%08" PRIx32
        " flow=%08" PRIx32 " endian=%08" PRIx32 "\n",
        stage, (unsigned)brg->clk_en.clk_en, (unsigned)brg->csi_en.csi_brg_en,
        (uint32_t)brg->host_ctrl.val, (uint32_t)brg->int_raw.val,
        (uint32_t)brg->data_type_cfg.val, (uint32_t)brg->frame_cfg.val,
        (uint32_t)brg->buf_flow_ctl.val, (uint32_t)brg->endian_mode.val);

  for (i = 0; i < 4; i++)
    {
      _info("CAMDIAG[%s] dma%d dar=%08" PRIx32 " block_ts=%08" PRIx32
            " status=%08" PRIx32 " sstat=%08" PRIx32 " dstat=%08" PRIx32 "\n",
            stage, i,
            (uint32_t)DW_GDMA.ch[i].dar0.val,
            (uint32_t)DW_GDMA.ch[i].block_ts0.val,
            (uint32_t)DW_GDMA.ch[i].status0.val,
            (uint32_t)DW_GDMA.ch[i].sstat0.val,
            (uint32_t)DW_GDMA.ch[i].dstat0.val);
    }

  _info("CAMDIAG[%s] dma  chen0=%08" PRIx32 " int_st0=%08" PRIx32
        " common_int_st0=%08" PRIx32 "\n",
        stage, (uint32_t)DW_GDMA.chen0.val, (uint32_t)DW_GDMA.int_st0.val,
        (uint32_t)DW_GDMA.common_int_st0.val);
}

/* TEMP-CAMERA-DIAG: sample the receive path over time.  A static dar means the
 * bridge never produced a DMA request, which is the signature of "bridge
 * receives no valid frame" as opposed to "DMA mis-armed".
 */

static void esp_csi_diag_series(void)
{
  int i;

  esp_csi_diag("t0");
  for (i = 1; i <= 3; i++)
    {
      up_mdelay(400);
      esp_csi_diag(i == 1 ? "t1" : (i == 2 ? "t2" : "t3"));
    }
}

/****************************************************************************
 * Name: esp_csi_data_start_capture
 ****************************************************************************/

  if (csi_start_err != ESP_OK)
    {
      _err("ERROR: esp_cam_ctlr_start failed: %d\n", (int)csi_start_err);
      priv->callback = NULL;
      priv->cbarg    = NULL;
      return -EIO;
    }

  /* TEMP-CAMERA-DIAG: sample host/bridge/DW-GDMA for ~1.2 s after arming. */

  esp_csi_diag_series();

  priv->streaming = true;
  return OK;
}

