  if (arg != NULL)
    {
      static const uint8_t sel[] =
      {
        0x25, 0x06, 0x14, 0x15, 0x22, 0x19, 0x16, 0x0a, 0x04
      };

      FAR csi_host_dev_t *host = MIPI_CSI_HOST_LL_GET_HW(0);
      size_t k;

      for (k = 0; k < sizeof(sel) / sizeof(sel[0]); k++)
        {
          uint32_t a;
          uint32_t b;

          mipi_csi_phy_ll_write_clock(host, 0, false);
          mipi_csi_phy_ll_write_reg_addr(host, 0x44);
